-- Script de inicialização do banco de dados

-- MySQL Workbench compatível

-- Criar banco de dados se não existir
CREATE DATABASE IF NOT EXISTS patrimonio_db;
USE patrimonio_db;

-- Tabela de equipamentos
CREATE TABLE IF NOT EXISTS equipamentos (
    ni VARCHAR(50) PRIMARY KEY,
    tag VARCHAR(100) NOT NULL,
    descricao VARCHAR(255) NOT NULL,
    sala VARCHAR(50) NULL,
    local VARCHAR(100) NULL,
    bloco VARCHAR(50) NULL,
    emp VARCHAR(100) NULL COMMENT 'Empresa',
    obs TEXT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Tabela de usuários
CREATE TABLE IF NOT EXISTS usuarios (
    id INT AUTO_INCREMENT PRIMARY KEY,
    username VARCHAR(50) UNIQUE NOT NULL,
    password VARCHAR(255) NOT NULL COMMENT 'Hash com bcrypt'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

